pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MStableYieldSource, ISavingsContractV2} from "../src/MStableYieldSource.sol";

contract InvMutTest is Test {
    MStableYieldSource c;
    function setUp() public { c = new MStableYieldSource(ISavingsContractV2(address(new __InvMutHandleStub()))); }
    function testFuzz_property(uint256 amount, address caller, address to) public {
        vm.assume(amount > 0);
        vm.assume(caller != address(0) && to != address(0));
        vm.assume(caller != to);
        vm.assume(uint160(caller) < type(uint160).max && uint160(to) < type(uint160).max);
        vm.prank(caller);
        c.supplyTokenTo(amount, to);
        // Rule: the credits issued for a supply must land on the beneficiary `to`.
        assertTrue(c.imBalances(to) == amount, "credits must be credited to beneficiary");
    }
}
